contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test takes parameters to exercise payable calls and arbitrary calldata/targets.
    // It checks that when invoked by this contract (not the original owner of C),
    // owner-only operations revert and do not change observable state, while the fallback
    // increments depositsCount when Ether is sent directly to C's address.
    function run(address target, uint256 value, bytes calldata data, uint256 sendToFallback) public payable {
        require(true);
        // Preconditions for sending Ether: ensure this contract has enough balance to forward
        if (sendToFallback > 0) {
            require(address(this).balance >= sendToFallback);
        }
        // Read observable state before actions
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        // Try withdrawAll (should be owner-only) and record whether it reverted
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Try withdraw(value)
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try sendMoney to arbitrary target with calldata
        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // If requested, send Ether to c to trigger fallback
        if (sendToFallback > 0) {
            // send Ether directly to c; this will trigger fallback() and increment depositsCount
            // Use low-level call from this contract
            (bool s,) = address(c).call{value: sendToFallback}("\x00");
            // ensure the external send succeeded; if it failed, we still proceed to assert properties
            // no try/catch here because we already executed the call
        }

        // Read observable state after actions
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount();

        // General rule (single assert):
        // - If any owner-only call did NOT revert when invoked from this contract, then C's balance must have decreased by at least the withdrawn amount(s) and/or the call must have been allowed; otherwise (the expected case), none of these owner-only calls change C's balance.
        // - Additionally, sending Ether directly to C increases depositsCount by exactly the number of successful direct calls (0 or 1 here).
        // We express this conservatively: if all owner-only calls reverted, balance change is only due to direct sends; otherwise balance change is >=0 and depositsCount increased by direct sends.

        bool allOwnerCallsReverted = withdrewAllReverted && withdrewReverted && sendMoneyReverted;

        // Compute expected deposits increment: either 0 or 1 depending on whether sendToFallback succeeded
        bool fallbackCalled = (afterDeposits == beforeDeposits + (sendToFallback > 0 ? 1 : 0));

        // Assert the invariant: if all owner-only calls reverted then the only allowed change to c.balance is from the direct fallback send;
        // hence afterBalance == beforeBalance + sendToFallback OR if any owner call succeeded then afterBalance <= beforeBalance + sendToFallback (owner could have withdrawn funds).
        assert(
            (allOwnerCallsReverted && afterBalance == beforeBalance + (sendToFallback > 0 ? sendToFallback : 0) && fallbackCalled)
            ||
            (!allOwnerCallsReverted && afterBalance <= beforeBalance + (sendToFallback > 0 ? sendToFallback : 0))
        );
    }

    // Allow this test contract to receive Ether so it can forward to C
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. Parameters: target and data for sendMoney, a value to attempt owner ops, and an amount to forward directly to C to trigger fallback.
    function run(address target, uint256 value, bytes calldata data, uint256 sendToFallback) public payable {
        require(address(this).balance >= sendToFallback);

        // Observe before state
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        // Try owner-only calls from this (non-owner) contract; each must be a top-level call
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // If requested, send Ether directly to C to invoke fallback (this is a plain external call, not via c.)
        if (sendToFallback > 0) {
            (bool s,) = address(c).call{value: sendToFallback}("\x00");
            // we do not require s; the success or failure will be reflected in balances and depositsCount
        }

        // Observe after state
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount();

        bool allOwnerCallsReverted = withdrewAllReverted && withdrewReverted && sendMoneyReverted;

        // If all owner-only calls reverted, then the only way c.balance can change is from the direct send above.
        // Also, a successful direct send causes fallback() to run and increment depositsCount by 1 per successful call.
        // Expressed as a single assert over observed values and parameters.
        assert(
            (allOwnerCallsReverted && afterBalance == beforeBalance + (sendToFallback > 0 ? sendToFallback : 0) && afterDeposits == beforeDeposits + (sendToFallback > 0 ? 1 : 0))
            ||
            (!allOwnerCallsReverted && afterDeposits >= beforeDeposits) // if an owner call succeeded, we only require depositsCount didn't decrease
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try owner-only functions and optionally send Ether directly to c to trigger fallback.
    // Parameters:
    // - target, valueForSendMoney, data: for c.sendMoney
    // - withdrawValue: for c.withdraw
    // - directSend: amount this contract will forward to c (must be <= this contract balance)
    function run(address target, uint256 valueForSendMoney, bytes calldata data, uint256 withdrawValue, uint256 directSend) public payable {
        require(address(this).balance >= directSend);

        // observe before state
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        // Attempt owner-only calls from this contract; each call is a top-level statement
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool withdrewReverted;
        try c.withdraw(withdrawValue) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, valueForSendMoney, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Optionally send Ether directly to c to invoke fallback (a plain external call)
        if (directSend > 0) {
            (bool ok, ) = address(c).call{value: directSend}("\x00");
            // success or failure reflected in balances and depositsCount; do not require ok
            ok; // silence unused-local-warning in some compilers
        }

        // observe after state
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount();

        bool allOwnerCallsReverted = withdrewAllReverted && withdrewReverted && sendMoneyReverted;

        // General rule: if all three owner-only calls from this non-owner reverted, then the only possible change
        // to c.balance is the directSend we forwarded, and each successful direct external send increments depositsCount by 1.
        // We express depositsCount change as either +1 when directSend>0 and the external call succeeded, or unchanged if it failed.
        // Because we cannot observe whether the low-level call succeeded except via balances/deposits, we require that
        // when allOwnerCallsReverted, afterBalance == beforeBalance + (directSend) and afterDeposits == beforeDeposits + (directSend > 0 ? 1 : 0)
        // OR that afterBalance==beforeBalance and afterDeposits==beforeDeposits when the external send failed.

        // To keep a single assert over observed values and params/revert flags:
        assert(
            (!allOwnerCallsReverted) ||
            (
                // if all owner calls reverted, then either directSend succeeded and both balance and deposits increased accordingly,
                // or directSend was 0 and nothing changed
                (directSend == 0 && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                ||
                (directSend > 0 && afterBalance == beforeBalance + directSend && afterDeposits == beforeDeposits + 1)
            )
        );
    }

    receive() external payable {}
}

