contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept inputs: which function to call (0=withdrawAll,1=withdraw,2=sendMoney), value to withdraw/send, target and data for sendMoney.
    function run(uint action, uint value, address target, bytes calldata data) public payable {
        require(true);

        // Record observable state before the call
        uint beforeDeposits = c.depositsCount();
        uint beforeContractBalance = address(c).balance;

        // Make the call as msg.sender = this contract (which is NOT the owner of c, since C was deployed externally by the checker)
        bool reverted;
        if (action == 0) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // For sendMoney, we may want to forward some Ether from this contract to C.call; but sendMoney is non-payable from caller to C, it simply makes C call target with value.
            // We just invoke it; if target requires gas or call fails, sendMoney will revert.
            try c.sendMoney(target, value, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observables after
        uint afterDeposits = c.depositsCount();
        uint afterContractBalance = address(c).balance;

        // General rule: if the caller is not owner (this contract), then the attempted mutating calls must revert and leave depositsCount and contract balance unchanged.
        // We cannot directly read owner, but owner is set to msg.sender at C construction; since the checker deploys a fresh C and passes it to our constructor, msg.sender at that time was the deployer (not this contract). Therefore this contract is non-owner.
        assert(reverted == true && afterDeposits == beforeDeposits && afterContractBalance == beforeContractBalance);
    }

    // Allow receiving Ether in case calls to c try to send Ether back to this contract during tests
    receive() external payable {}
}

