contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that non-owner calls to withdraw/withdrawAll/sendMoney revert,
    // while depositsCount increments only via fallback payable being called.
    // Parameters:
    // - callType: 0 = withdrawAll, 1 = withdraw(_value), 2 = sendMoney(target, value, data), 3 = send fallback (value)
    // - v: amount of wei to supply for calls that send ETH to c (when this contract sends to c)
    // - value: amount argument for withdraw/sendMoney
    // - target: target address for sendMoney
    // - data: bytes data for sendMoney
    function run(uint8 callType, uint v, uint value, address target, bytes calldata data) public payable {
        require(callType <= 3);
        // Ensure this contract has enough balance to forward v if needed
        if (v > 0) require(address(this).balance >= v);

        // Read pre-state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool reverted = false;

        // Perform action as this contract (which is NOT the owner of c, since c was deployed with owner = msg.sender at C deployment,
        // but per checker, C was deployed freshly and constructor param provided is that instance; our InvMutTest is not the owner)
        if (callType == 0) {
            // withdrawAll
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (callType == 1) {
            // withdraw
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (callType == 2) {
            // sendMoney
            // If v > 0, we don't send Ether to c here; sendMoney transfers from c to target, so no value forwarded to c.
            try c.sendMoney(target, value, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call fallback by sending Ether to c
            // Send v wei to c to trigger fallback payable
            if (v > 0) {
                // perform low-level send to address(c) to trigger fallback
                (bool ok, ) = address(c).call{value: v}("\x00");
                // treat as revert if call failed
                reverted = !ok;
            } else {
                // sending zero value still triggers fallback but doesn't increase balance; do call with empty data
                (bool ok, ) = address(c).call("");
                reverted = !ok;
            }
        }

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule asserted:
        // - If the call was withdraw/withdrawAll/sendMoney (callType 0..2), then because this contract is NOT the owner,
        //   the call must revert (i.e., reverted == true). Exception: if somehow this contract equals the owner, then the call may succeed.
        // - If callType == 3 (fallback invocation by sending v wei), then depositsCount increases by 1 iff the low-level call succeeded and v>0 (balance increased).
        // We express this without referring to internal owner variable: we detect owner-ness by comparing observed behavior when calling withdrawAll with 0 value:

        // Determine whether this InvMutTest is the owner by attempting a benign withdraw of 0 and observing whether it would revert.
        bool amOwner;
        try c.withdraw(0) {
            amOwner = true;
        } catch {
            amOwner = false;
        }

        if (callType <= 2) {
            // If amOwner then the attempted operation may succeed; else it must revert.
            if (amOwner) {
                // when owner, the call should not have necessarily reverted (we assert nothing stronger than possibility),
                assert(true);
            } else {
                // when not owner, any of those calls must revert
                assert(reverted == true);
            }
        } else {
            // callType == 3: fallback invoked
            if (reverted) {
                // if fallback call reverted, depositsCount must be unchanged and balance unchanged
                assert(afterDeposits == beforeDeposits && afterBal == beforeBal);
            } else {
                // success: depositsCount increased by exactly 1 and balance increased by v
                // (fallback increments depositsCount unconditionally on payable fallback)
                assert(afterDeposits == beforeDeposits + 1 && afterBal == beforeBal + v);
            }
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // callType: 0=withdrawAll, 1=withdraw(amount), 2=sendMoney(target,amount,data), 3=invoke fallback by sending eth
    // v: value in wei to send when invoking fallback (only used for callType==3)
    // amount: argument for withdraw or sendMoney
    // target: target address for sendMoney
    // data: calldata for sendMoney
    function run(uint8 callType, uint v, uint amount, address target, bytes calldata data) public payable {
        require(callType <= 3);
        if (v > 0) require(address(this).balance >= v);

        // Read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Determine whether this test contract is the owner by attempting a benign withdraw of 0 and observing revert
        bool ownerProbeReverted;
        try c.withdraw(0) {
            ownerProbeReverted = false;
        } catch {
            ownerProbeReverted = true;
        }
        bool amOwner = !ownerProbeReverted;

        // Perform the chosen action. Each state-changing call on c must be its own top-level statement.
        bool actionReverted;
        if (callType == 0) {
            try c.withdrawAll() {
                actionReverted = false;
            } catch {
                actionReverted = true;
            }
        } else if (callType == 1) {
            try c.withdraw(amount) {
                actionReverted = false;
