contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll attempt an owner action (should succeed) and then a non-owner action (should revert and not change state).
    // Parameters:
    // - sendAmount: amount of wei to send into c via its fallback (to increase depositsCount and balance)
    // - withdrawAmount: amount to withdraw as owner
    // - attacker: address to attempt non-owner calls from (simulated by calling c.sendMoney with data that will forward to attacker)
    function run(uint sendAmount, uint withdrawAmount, address payable attacker) public payable {
        require(address(this).balance >= sendAmount, "insufficient test balance");

        // 1) As owner (this contract is owner because it deployed C), send Ether to c using fallback to increment depositsCount
        c.call{value: sendAmount}(new bytes(0)); // invoke fallback by low-level call; changes c.balance and depositsCount

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Owner withdrawAll should succeed and reduce c balance to 0 (or at least by withdrawAmount when using withdraw)
        // Use withdraw to withdraw withdrawAmount
        // Ensure withdrawAmount <= beforeBalance to avoid revert from transfer
        if (withdrawAmount > beforeBalance) {
            withdrawAmount = beforeBalance;
        }
        c.withdraw(withdrawAmount);

        uint afterWithdrawBalance = address(c).balance;
        uint depositsAfterWithdraw = c.depositsCount();

        // Now attempt a non-owner action: we cannot change msg.sender for calls, but we can attempt to send money to an attacker address
        // using sendMoney with target=attacker. Since onlyOwner restricts it, it should succeed when called by owner (this contract).
        // To test non-owner revert, we simulate a call from attacker by calling a method on c that will call attacker via low-level call
        // But we cannot change msg.sender in this test. Instead, we assert a general rule: only owner can call sendMoney/withdraw —
        // observable by that when owner calls, it changes balance and when a call would be made by a non-owner it must revert.
        // We capture that by checking owner-call effects and asserting non-owner calls would revert logically: attempt to call
        // withdraw from a non-owner cannot be done here, so we express the rule as implication about public owner identity

        // Read owner address from c via its public getter
        address owner = c.owner();

        // The intended general rule: if this contract is owner, then withdraw succeeded and decreased c.balance by withdrawAmount
        // and did not change depositsCount. Additionally, the owner getter equals this contract's address.
        assert(owner == address(this) && beforeDeposits == depositsAfterWithdraw && beforeBalance - afterWithdrawBalance == withdrawAmount);
    }

    receive() external payable { }
}

