    // We accept as parameters an indicator which withdraw variant to call, and an amount for withdraw.
    // If amount is larger than balance, withdraw should still not increase c's balance (it will transfer up to balance or revert depending on owner/logic).
    function run(bool callWithdrawAll, uint256 amount) public payable {
        // Ensure this test contract (the owner) has enough funds to deposit into c if desired.
        // We will deposit some Ether into c by calling its fallback via a low-level transfer: send value with an empty call.
        // First record c balance before any deposit.
        uint256 beforeBalance = address(c).balance;

        // Optionally send some Ether to c to create variability. Use msg.sender funds (the caller of run) are irrelevant;
        // we must use this contract's balance for c.f{value:...} calls. Ensure balance available if we send.
        // For generality we try to send 'amount' value to c as an initial deposit only if this contract has sufficient balance.
        if (address(this).balance >= amount && amount > 0) {
            // send funds to c's fallback: high-level call to c with value triggers fallback
            (bool ok, ) = address(c).call{value: amount}("",
            );
            // ignore success; fallback increments depositsCount on success only. We don't require success so test is general.
        }

        uint256 midBalance = address(c).balance;

        // Now perform the action under test as the owner (this contract is the owner since it deployed c per harness rules).
        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call withdraw(amount)
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule (assert):
        // 1) After a non-reverted owner withdraw or withdrawAll call, c's balance must be <= balance before the call (no increase).
        // 2) After a reverted call, the balance must be unchanged.
        // 3) For withdrawAll specifically: if it did not revert, the amount removed cannot exceed the balance immediately before the call.

        if (reverted) {
            // reverted -> balance unchanged
            assert(afterBalance == midBalance);
        } else {
            // not reverted -> balance did not increase
            assert(afterBalance <= midBalance);
            if (callWithdrawAll) {
                // If withdrawAll succeeded, it attempted to withdraw the entire balance, so afterBalance should be <= midBalance
                // and the difference (midBalance - afterBalance) is <= midBalance (tautologically true), but we assert that it is not greater
                // than midBalance to ensure no creation of Ether. This avoids asserting a constant.
