contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use a single public payable function that performs a plain top-level call on c
    // by invoking the C.fallback via c.withdraw with zero to avoid changing balance is not suitable.
    // However, to satisfy the constraint that state-changing calls on c must be of the form c.f(...)
    // and top-level, we will use c.sendMoney targeting address(c) with provided data "" to invoke
    // an external call to C itself. sendMoney is public and onlyOwner in C; since InvMutTest is the
    // deployer of C (per the harness), InvMutTest is the owner and can call sendMoney. sendMoney will
    // perform _target.call{value:_value}(_data), which for _target = address(c) and _data = "" triggers
    // the fallback of C as a plain top-level call on c.

    function run(address target, uint256 amount, bytes calldata data) public payable {
        // require we have enough balance to forward
        require(address(this).balance >= amount);
        // preconditions: need target to be address(c) to trigger fallback of C
        require(target == address(c));

        // read before values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBalance = address(c).balance;

        // top-level state-changing call on c: call sendMoney which will perform call to target (C) with value and data
        c.sendMoney(target, amount, data);

        // read after values
        uint256 afterCount = c.depositsCount();
        uint256 afterBalance = address(c).balance;

        // If the inner call from sendMoney succeeded then it will have invoked the fallback on C and
        // incremented depositsCount by 1 and increased balance by amount. sendMoney itself uses require on
        // the low-level call result, so sendMoney reverts on failure; therefore when this point is reached,
        // the inner call succeeded. Thus the general rule: afterCount == beforeCount + 1 and afterBalance == beforeBalance + amount.
        assert(afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We receive Ether so that this contract can fund c when needed
    receive() external payable {}

    // params: callerIsOwner - if true we act as owner (we are owner because we deployed c),
    // amount - value to send to c before withdrawals, withdrawAmount - amount to withdraw via withdraw
    function run(bool callerIsOwner, uint amount, uint withdrawAmount) public payable {
        require(address(this).balance >= amount);

        // initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // fund c by calling its fallback with Ether: fallback increments depositsCount
        // We call it unconditionally to set up depositsCount change behavior
        // Sending 'amount' may be zero.
        c.call{value: amount}("0x");

        uint afterFundDeposits = c.depositsCount();
        uint afterFundBal = address(c).balance;

        // Now attempt withdraw or withdrawAll depending on callerIsOwner
        bool withdrew; 
        bool didRevert = false;
        // We are the owner of c (c was deployed with msg.sender being this InvMutTest's deployer),
        // but to model a non-owner attempt we cannot change msg.sender here; so callerIsOwner=false will
        // simulate a non-owner by trying to call withdraw via a low-level call from a different address.
        // However constraints forbid changing msg.sender. Therefore interpret callerIsOwner: if true, call
        // withdraw; if false, attempt a call that will revert by providing an invalid low-level call
        // (simulate non-owner revert) — but we must only interact via c's public surface. So instead,
        // when callerIsOwner==true we call withdraw(withdrawAmount), else we call a function that will revert
        // by calling sendMoney to address(0) with too large value (likely revert). To keep within constraints,
        // we use try/catch on c.withdraw.

        if (callerIsOwner) {
            try c.withdraw(withdrawAmount) {
                withdrew = true;
            } catch {
                didRevert = true;
                withdrew = false;
            }
        } else {
            // Non-owner path: calling withdraw will revert due to onlyOwner modifier
            try c.withdraw(withdrawAmount) {
                withdrew = true;
            } catch {
                didRevert = true;
                withdrew = false;
            }
        }

        uint finalDeposits = c.depositsCount();
        uint finalBal = address(c).balance;

        // General rule asserted:
        // - depositsCount only changed due to the funding call and equals before + (amount>0 ? 1 : 0)
        //   (fallback increments on any fallback payable call regardless of amount > 0; but EVM allows zero-value too)
        //   To be safe, assert that depositsCount did not decrease and is at least beforeDeposits.
        // - If callerIsOwner and withdraw did not revert, then finalBal = afterFundBal - withdrawAmount
        //   (cannot underflow) and depositsCount unchanged by withdraw call.
        // - If callerIsOwner is false, withdraw must revert (didRevert==true) and balances unchanged by withdraw.

        assert(
            // depositsCount never decreased and withdraw never increases it
            finalDeposits >= afterFundDeposits
            // depositsCount unchanged by withdraw attempts: withdraw cannot increase depositsCount
            && (finalDeposits == afterFundDeposits)
            // If non-owner attempted withdraw, it must have reverted and contract balance unchanged by withdraw
            && ( (!callerIsOwner && didRevert && finalBal == afterFundBal)
                 // If owner attempted withdraw and it did not revert, final balance decreased by exactly withdrawAmount
                 || ( callerIsOwner && !didRevert && finalBal + withdrawAmount == afterFundBal )
               )
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // allow this contract to receive Ether so tests can fund C
    receive() external payable {}

    // params:
    // fundAmount - amount of wei to send to C's fallback (can be zero)
    // withdrawAmount - amount to attempt to withdraw via c.withdraw
    // callAsOwner - if true we call withdraw (we are C's owner because this contract deployed C),
    //               if false we still call withdraw to observe it reverting (but in this setup msg.sender is always this contract,
    //               so callAsOwner=false models the expectation that withdraw would revert if not owner; here it will succeed)
    // Note: checker deploys a fresh C with owner = msg.sender (the deployer). In our environment InvMutTest deployed C, so
    // this contract is the owner and withdraw will succeed. We still keep callAsOwner to let the prover consider both branches
    // and assert accordingly based on actual revert outcome.
    function run(uint fundAmount, uint withdrawAmount, bool callAsOwner) public payable {
        // ensure this test contract has enough balance to fund C
        require(address(this).balance >= fundAmount);

        // read initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // fund C by invoking its fallback via address(c).call with value
        (bool sent, ) = address(c).call{value: fundAmount}("\x00");
        // the fallback is payable and should accept the call; if it reverts, we record that fact
        bool fundReverted = !sent;

        uint afterFundDeposits = c.depositsCount();
        uint afterFundBal = address(c).balance;

        // attempt withdraw and record if it reverted
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint finalDeposits = c.depositsCount();
        uint finalBal = address(c).balance;

        // Assert the general rule:
        // - If the funding call did not revert then depositsCount increased by exactly 1 and balance increased by fundAmount.
        // - Funding never decreases depositsCount or balance.
        // - The withdraw call, if it did not revert, does not change depositsCount and decreases C's balance by exactly withdrawAmount.
        // - If withdraw reverted then it did not change depositsCount or balance.
        assert(
            // funding safety: depositsCount did not decrease and balance did not decrease
            finalDeposits >= beforeDeposits
            && afterFundBal >= beforeBal

            // if funding succeeded, depositsCount increased by exactly 1 and balance increased by fundAmount
            && ( fundReverted
                 ? (afterFundDeposits == beforeDeposits && afterFundBal == beforeBal)
                 : (afterFundDeposits == beforeDeposits + 1 && afterFundBal == beforeBal + fundAmount)
               )

            // withdraw effects: it never increases depositsCount
            && finalDeposits >= afterFundDeposits
            && ( finalDeposits == afterFundDeposits )

            // if withdraw succeeded, final balance decreased by withdrawAmount; if reverted, balance unchanged
            && ( withdrawReverted ? (finalBal == afterFundBal) : (afterFundBal == finalBal + withdrawAmount) )
        );
    }
}

