    C c;
    constructor(C _c) { c = _c; }

    // Test: owner (this contract) calls withdrawAll or withdraw; ensure balance decreases appropriately and depositsCount unchanged.
    // Parameters:
    // - useWithdrawAll: if true call withdrawAll(), else call withdraw(amount)
    // - amount: amount passed to withdraw when useWithdrawAll == false
