    function run(bool useWithdrawAll, uint256 amount) public payable {
        // Ensure this test contract has enough ETH to deposit into c if needed
        require(address(this).balance >= msg.value);

        // First, send some ether into c by calling c.sendMoney to self (onlyOwner) to set up balance.
        // Use a top-level call on c to change state (this contract is owner so sendMoney should succeed).
        // We choose target = address(this) and data = "" so payable fallback on this contract receives funds.
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // Fund c by calling sendMoney with value = msg.value. This will perform an external call from c to this contract
        // but will deduct from c's balance only if c had funds; to actually increase c balance we instead send Ether directly to c
        // by invoking c.sendMoney with 0 value is pointless; instead perform a top-level call to c's fallback by calling c.sendMoney is not suitable.
        // To increase c.balance we perform a top-level call that is allowed: call c.sendMoney with target = address(this) and value = 0
        // but that doesn't increase balance. Therefore we instead require amount to be <= beforeBal for withdraw path.

        // Decide which withdraw to invoke. We must make the state-changing call as its own top-level statement.
        bool reverted;
        if (useWithdrawAll) {
            // Call withdrawAll as owner
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // General rule:
        // - depositsCount must not change as a result of withdraw/withdrawAll calls
        // - If the call reverted then balance unchanged; if it succeeded then balance decreased by either amount (for withdraw)
        //   or by at most the previous balance (for withdrawAll), i.e., afterBal == beforeBal - amount when withdraw succeeded and amount <= beforeBal,
        //   or afterBal == 0 when withdrawAll succeeded.
        // Expressed in a single assert.
        if (useWithdrawAll) {
            // For withdrawAll: if not reverted then afterBal == 0 and beforeBal >= afterBal
            assert(afterCount == beforeCount && (reverted ? afterBal == beforeBal : afterBal == 0));
        } else {
            // For withdraw(amount): if not reverted then afterBal == beforeBal - amount (if amount <= beforeBal) else it should have reverted.
            // We express: either reverted and balance unchanged, or not reverted and beforeBal >= amount and afterBal == beforeBal - amount.
            assert(afterCount == beforeCount && (reverted ? afterBal == beforeBal : (beforeBal >= amount && afterBal == beforeBal - amount)));
        }
    }

