        // Call withdraw as owner (this contract deployed C so it is owner). Top-level state-changing call using c.withdraw
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after the call
        uint afterBalance = address(c).balance;
        uint afterDepositsCount = c.depositsCount();

        // If the call reverted then nothing is guaranteed beyond revert; if it didn't revert then:
        // - depositsCount must not decrease
        // - balance must become either beforeBalance - withdrawAmount (if withdrawAmount <= beforeBalance)
        //   or 0 (if withdrawAmount > beforeBalance), because transfer withdraws up to the available balance.
        bool balanceOK = (reverted) || (
            (withdrawAmount <= beforeBalance && afterBalance == beforeBalance - withdrawAmount) ||
            (withdrawAmount > beforeBalance && afterBalance == 0)
        );

        assert(balanceOK && (reverted || afterDepositsCount >= beforeDepositsCount));
    }

    // Allow this contract to receive Ether so it can fund C and receive withdrawals.
    receive() external payable {}
}

